<?php
require_once __DIR__.'/includes/auth.php';require_roles(['ADMIN','ORGANIZADOR']);require_once __DIR__.'/includes/helpers.php';$pageTitle='Sanciones y premiación';
try{$torneos=option_map('torneos');$jugadores=option_map('jugadores');$arbitros=option_map('arbitros');$equipos=option_map('equipos');$selected=$_GET['torneo']??($_POST['torneo_contexto']??array_key_first($torneos));$sanciones=$selected?oracle_cursor('AV_JP_RM_BE_SP_SANCION_LISTAR',['P_ID_TORNEO'=>$selected]):[];$premios=$selected?oracle_cursor('AV_JP_RM_BE_SP_PREMIACION_LISTAR',['P_ID_TORNEO'=>$selected]):[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['sancion'])){$sql="BEGIN AV_JP_RM_BE_SP_REGISTRAR_SANCION(:P_ID_TORNEO,:P_ID_JUGADOR,:P_ID_ARBITRO,:P_TIPO,:P_MOTIVO,:P_PUNTOS_DESCUENTO,CASE WHEN :P_FECHA_FIN IS NULL THEN NULL ELSE TO_DATE(:P_FECHA_FIN,'YYYY-MM-DD') END,:P_ID_SANCION); END;";$p=['P_ID_TORNEO'=>$_POST['torneo_contexto'],'P_ID_JUGADOR'=>$_POST['jugador'],'P_ID_ARBITRO'=>$_POST['arbitro'],'P_TIPO'=>$_POST['tipo'],'P_MOTIVO'=>$_POST['motivo'],'P_PUNTOS_DESCUENTO'=>$_POST['puntos'],'P_FECHA_FIN'=>$_POST['fecha_fin']?:null,'P_ID_SANCION'=>0];oracle_run($sql,$p,['P_ID_SANCION']);flash('success','Sanción registrada.');}
 if(isset($_POST['premio'])){$p=['P_ID_TORNEO'=>$_POST['torneo_contexto'],'P_ID_EQUIPO'=>$_POST['equipo'],'P_POSICION'=>$_POST['posicion'],'P_MONTO'=>$_POST['monto'],'P_ID_PREMIACION'=>0];oracle_run('BEGIN AV_JP_RM_BE_SP_REGISTRAR_PREMIO(:P_ID_TORNEO,:P_ID_EQUIPO,:P_POSICION,:P_MONTO,:P_ID_PREMIACION); END;',$p,['P_ID_PREMIACION']);flash('success','Premiación registrada.');}
 header('Location: gestor_sanciones.php?torneo='.urlencode($_POST['torneo_contexto']));exit;}}
catch(Throwable $e){$error=$e->getMessage();}
include __DIR__.'/includes/header.php';function op($a){foreach($a as $v=>$l)echo '<option value="'.h($v).'">'.h($l).'</option>';}?>
<main class="content"><div class="page-head"><div><h1>🚨 Sanciones y premiación</h1><p>Gestor 5: aplica disciplina con descuento de puntos y registra la premiación final.</p></div></div><?php if(!empty($error)):?><div class="callout" style="border-color:#ff667d"><?=h($error)?></div><?php endif;?><form method="get" class="panel" style="margin-bottom:16px"><div class="field"><label>Torneo</label><select name="torneo" onchange="this.form.submit()"><?php foreach($torneos??[] as $v=>$l):?><option value="<?=h($v)?>" <?=((string)$v===(string)$selected)?'selected':''?>><?=h($l)?></option><?php endforeach;?></select></div></form><div class="grid grid-2"><section class="panel"><h2 class="section-title">Registrar sanción</h2><form method="post"><input type="hidden" name="sancion" value="1"><input type="hidden" name="torneo_contexto" value="<?=h($selected)?>"><div class="field"><label>Jugador</label><select name="jugador" required><?php op($jugadores??[])?></select></div><div class="field"><label>Árbitro</label><select name="arbitro" required><?php op($arbitros??[])?></select></div><div class="field"><label>Tipo</label><select name="tipo"><option value="AMONESTACION">Amonestación</option><option value="SUSPENSION">Suspensión</option><option value="DESCUENTO_PUNTOS">Descuento de puntos</option></select></div><div class="field"><label>Motivo</label><textarea name="motivo" required></textarea></div><div class="grid grid-2"><div class="field"><label>Puntos a descontar</label><input type="number" min="0" name="puntos" value="0"></div><div class="field"><label>Fin suspensión</label><input type="date" name="fecha_fin"></div></div><div class="form-actions"><button class="btn">Registrar sanción</button></div></form></section><section class="panel"><h2 class="section-title">Registrar premiación</h2><form method="post"><input type="hidden" name="premio" value="1"><input type="hidden" name="torneo_contexto" value="<?=h($selected)?>"><div class="field"><label>Equipo</label><select name="equipo" required><?php op($equipos??[])?></select></div><div class="field"><label>Posición</label><input type="number" min="1" name="posicion" required></div><div class="field"><label>Monto</label><input type="number" min="0" name="monto" required></div><div class="form-actions"><button class="btn">Registrar premio</button></div></form><div class="callout" style="margin-top:16px">Registrar la posición 1 marca el torneo como <strong>FINALIZADO</strong>.</div></section></div><div class="grid grid-2" style="margin-top:16px"><section class="panel"><h2 class="section-title">Sanciones</h2><div class="table-wrap"><table><thead><tr><th>Jugador</th><th>Tipo</th><th>Motivo</th><th>Puntos</th><th>Estado</th></tr></thead><tbody><?php foreach($sanciones??[] as $r):?><tr><td><?=h($r['NICKNAME'])?></td><td><?=h($r['TIPO'])?></td><td><?=h($r['MOTIVO'])?></td><td><?=h($r['PUNTOS_DESCUENTO'])?></td><td><?=h($r['ESTADO'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2 class="section-title">Premiación</h2><div class="table-wrap"><table><thead><tr><th>Equipo</th><th>Posición</th><th>Monto</th><th>Fecha</th></tr></thead><tbody><?php foreach($premios??[] as $r):?><tr><td><?=h($r['EQUIPO'])?></td><td>#<?=h($r['POSICION'])?></td><td><?=money($r['MONTO'])?></td><td><?=h($r['FECHA'])?></td></tr><?php endforeach;?></tbody></table></div></section></div></main><?php include __DIR__.'/includes/footer.php';?>
